pragma solidity 0.8.25;

import "../../lib/ValidContract.sol";
import "../CnV3/ICnStakingV3.sol";
import "./IPublicDelegation.sol";
import "./PublicDelegationStorage.sol";
import "openzeppelin-contracts-5.0/access/Ownable.sol";
